mapper.select:
SELECT 
FROM sys_announcement a LEFT JOIN sys_user u ON u.uuid = a.publisher_id
WHERE a.uuid = #{id}

mapper.update:
UPDATE sys_announcement SET title = #{title}, content = #{content},
    update_user_id = #{operatorId}
WHERE uuid = #{id} AND status = 0

UPDATE sys_announcement SET status = 1, publisher_id = #{operatorId},
    publish_time = NOW(), update_user_id = #{operatorId}
WHERE uuid = #{id} AND status = 0

UPDATE sys_announcement SET status = 2,
    update_user_id = #{operatorId}
WHERE uuid = #{id} AND status = 1
